#include <iostream>
#include <string>

class Automobile {
private:
    std::string model;
    int speed;

public:
    Automobile(std::string m, int initialSpeed)
        : model(std::move(m)), speed(initialSpeed) {}

    void pressAccelerator(int delta) {
        if (delta > 0) {
            speed += delta;
        }
    }

    int getSpeed() const {
        return speed;
    }

    const std::string& getModel() const {
        return model;
    }
};

class Convertible : public Automobile {
private:
    bool roofOpen;

public:
    Convertible(std::string m, int initialSpeed, bool isRoofOpen)
        : Automobile(std::move(m), initialSpeed), roofOpen(isRoofOpen) {}

    bool isRoofOpened() const {
        return roofOpen;
    }
};

int main() {
    Convertible sportsCar("Roadster", 50, true);
    sportsCar.pressAccelerator(25);

    std::cout << "Model: " << sportsCar.getModel() << "\n";
    std::cout << "Speed: " << sportsCar.getSpeed() << " km/h\n";
    std::cout << "Roof open: " << (sportsCar.isRoofOpened() ? "true" : "false") << "\n";

    return 0;
}

